#!/usr/bin/env python3
"""Replace course practice and checkpoint placeholders with real multilingual MCQs."""
from __future__ import annotations

import json
import re
from copy import deepcopy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
COURSES = ROOT / "backend/src/data/courses.json"
LANGS = ["en", "hi", "ta", "te", "kn", "ml"]
NATIVE = ["hi", "ta", "te", "kn", "ml"]
LATIN = re.compile(r"[A-Za-z]")


def T(en, hi, ta, te, kn, ml):
    return {"en": en, "hi": hi, "ta": ta, "te": te, "kn": kn, "ml": ml}


def Q(qid, image, correct, question, options, explanation):
    assert len(options) == 4 and 0 <= correct < 4, qid
    for lang in NATIVE:
        assert not LATIN.search(question[lang]), f"{qid} question.{lang}: {question[lang]}"
        assert not LATIN.search(explanation[lang]), f"{qid} expl.{lang}: {explanation[lang]}"
        for i, opt in enumerate(options):
            assert not LATIN.search(opt[lang]), f"{qid} opt{i}.{lang}: {opt[lang]}"
    return {
        "id": qid,
        "image": image,
        "correct_index": correct,
        "question": question,
        "options": options,
        "explanation": explanation,
    }


def with_ids(bank, course_id):
    """Deep-copy bank and rewrite ids unique to course_id."""
    lessons = []
    for li, lesson_qs in enumerate(bank["lessons"]):
        new_qs = []
        for qi, q in enumerate(lesson_qs):
            nq = deepcopy(q)
            nq["id"] = f"{course_id}-l{li + 1}-pq{qi + 1}"
            new_qs.append(nq)
        lessons.append(new_qs)
    ckpt = []
    for qi, q in enumerate(bank["checkpoint"]):
        nq = deepcopy(q)
        nq["id"] = f"{course_id}-cp{qi + 1}"
        ckpt.append(nq)
    return lessons, ckpt


